using System;
using System.IO;
using System.Linq;
using CrossVault.FoxDbf.Expressions;
using CrossVault.FoxDbf.Index;
using CrossVault.FoxDbf.MicroVfp;
using CrossVault.FoxDbf.Query;
using CrossVault.FoxDbf.Sql;
using CrossVault.FoxDbf.Write;
using Xunit;

namespace CrossVault.FoxDbf.Tests;

/// <summary>
/// Key TYPE of CDX tags whose KEY is an expression, read from a VFP9-built index
/// (<c>vfp_test/exprtags/</c>, regenerated by <c>mkexprtags.prg</c>). VFP9 types the expressions the way
/// the static type inference does — <c>TYPE("id+1")</c> on an Integer field is <c>N</c>, and the tag stores an
/// 8-byte numeric key — so the reader must not fall back to "unknown, assume character": that made
/// <see cref="CdxTag.Seek(object)"/> answer NotFound for every expression tag and decoded numeric / date
/// expression keys as character keys.
/// </summary>
public sealed class CdxExpressionKeyTypeTests : IDisposable
{
    private readonly SqlTestSupport.TempDir _dir = new();
    private readonly string _dbf;

    public CdxExpressionKeyTypeTests()
    {
        foreach (var file in Directory.GetFiles(Fixtures.VfpTest("exprtags")))
            if (!file.EndsWith(".prg", StringComparison.OrdinalIgnoreCase))
                File.Copy(file, Path.Combine(_dir.Path, Path.GetFileName(file)));
        _dbf = Path.Combine(_dir.Path, "exprtags.dbf");
    }

    public void Dispose() => _dir.Dispose();

    // Rows: (id, cust, no, d, amt) = (1,'alfki',7,2020-01-02,10.50) (2,'Bonap',12,2021-03-04,-5.25)
    //                                 (3,'chops',3,2019-12-31,99.99) (4,'ALFKI',12,2020-01-02,0.00)

    [Theory]
    [InlineData("TID", IndexKeyType.Integer, false)]
    [InlineData("TIDP1", IndexKeyType.Numeric, false)]   // id+1: VFP TYPE() = N, 8-byte key
    [InlineData("TNO2", IndexKeyType.Numeric, false)]
    [InlineData("TAMT2", IndexKeyType.Numeric, false)]
    [InlineData("TYR", IndexKeyType.Numeric, false)]
    [InlineData("TD", IndexKeyType.Date, false)]
    [InlineData("TDP1", IndexKeyType.Date, false)]
    [InlineData("TCS", IndexKeyType.Character, true)]
    [InlineData("TDS", IndexKeyType.Character, true)]
    [InlineData("TUP", IndexKeyType.Character, true)]
    [InlineData("TUPG", IndexKeyType.Character, true)]   // GENERAL-collated
    public void ExpressionTag_KeyTypeAndCharacterFlag_MatchVfp9(string tag, IndexKeyType type, bool isChar)
    {
        using var table = DbfTable.Open(_dbf);
        using var cdx = CdxFile.Open(Path.ChangeExtension(_dbf, ".CDX"), table);

        var t = cdx.Tag(tag)!;
        Assert.Equal(type, t.KeyType);
        Assert.Equal(isChar, t.IsCharacterKey);
    }

    [Theory]
    [InlineData("TCS", "alfki    7", 1u)]
    [InlineData("TDS", "20210304", 2u)]
    [InlineData("TUP", "ALFKI", 1u)]
    [InlineData("TUPG", "BONAP", 2u)]
    public void Seek_CharacterExpressionTag_FindsTheRow(string tag, string key, uint recno)
    {
        using var table = DbfTable.Open(_dbf);
        using var cdx = CdxFile.Open(Path.ChangeExtension(_dbf, ".CDX"), table);

        Assert.Equal(recno, cdx.Tag(tag)!.Seek(key));
    }

    [Fact]
    public void Seek_NumericAndDateExpressionTags_FindTheRow()
    {
        using var table = DbfTable.Open(_dbf);
        using var cdx = CdxFile.Open(Path.ChangeExtension(_dbf, ".CDX"), table);

        Assert.Equal(2u, cdx.Tag("TIDP1")!.Seek(3m));
        Assert.Equal(2u, cdx.Tag("TNO2")!.Seek(24m));
        Assert.Equal(3u, cdx.Tag("TAMT2")!.Seek(199.98m));
        Assert.Equal(3u, cdx.Tag("TYR")!.Seek(2019m));
        Assert.Equal(1u, cdx.Tag("TDP1")!.Seek(new DateOnly(2020, 1, 3)));
        Assert.Null(cdx.Tag("TNO2")!.Seek(25m));
    }

    [Fact]
    public void NumericExpressionTag_KeysDecodeToTheExpressionValues()
    {
        using var table = DbfTable.Open(_dbf);
        using var cdx = CdxFile.Open(Path.ChangeExtension(_dbf, ".CDX"), table);
        var tag = cdx.Tag("TNO2")!;

        var decoded = tag.EnumerateEntries().Select(e => (e.RecordNumber, tag.DecodeKey(e.Key).AsDouble)).ToArray();

        Assert.Equal(new (uint, double?)[] { (3, 6), (1, 14), (2, 24), (4, 24) }, decoded);
    }

    [Theory]
    [InlineData("id+1")]
    [InlineData("no*2")]
    [InlineData("amt*2")]
    [InlineData("YEAR(d)")]
    [InlineData("d+1")]
    [InlineData("cust+STR(no,4)")]
    [InlineData("DTOS(d)")]
    [InlineData("UPPER(cust)")]
    public void ReaderType_AgreesWithTheBuilderType(string expression)
    {
        using var table = DbfTable.Open(_dbf);
        Assert.Equal(CdxIndexBuilder.ResolveKey(table, expression).Type, IndexKey.ResolveType(expression, table));
    }

    [Fact]
    public void ResolveType_WithoutATable_IsUnknown()
        => Assert.Equal(IndexKeyType.Unknown, IndexKey.ResolveType("no*2", null));

    [Theory]
    [InlineData("no*2 > 10")]
    [InlineData("no*2 = 24")]
    [InlineData("YEAR(d) = 2020")]
    [InlineData("id+1 >= 3")]
    [InlineData("d+1 = {^2020-01-03}")]
    [InlineData("DTOS(d) = '20200102'")]
    [InlineData("UPPER(cust) = 'ALFKI'")]
    public void Optimizer_OnExpressionTags_MatchesAFullScan(string filter)
    {
        using var table = DbfTable.Open(_dbf);
        using var cdx = CdxFile.Open(Path.ChangeExtension(_dbf, ".CDX"), table);
        var ctx = new EvaluationContext();

        var indexed = QueryOptimizer.FindRecords(table, cdx, filter, ctx).RecordNumbers;
        var scanned = QueryOptimizer.FindRecords(table, null, filter, ctx).RecordNumbers;

        Assert.Equal(scanned, indexed);
        Assert.NotEmpty(scanned);
    }

    [Fact]
    public void MicroVfp_SetKey_OnANumericExpressionTag_RestrictsTheRows()
    {
        // Used to throw "the controlling index key type cannot be decoded" — the type was Unknown.
        using var session = new VfpSession();
        session.OpenDirectory(_dir.Path);
        var vfp = new VfpInterpreter(session);

        vfp.Execute("USE exprtags\nSET ORDER TO TAG tno2\nSET KEY TO 24\nlcIds = ''\n" +
                    "SCAN\nlcIds = lcIds + STR(id, 1)\nENDSCAN");

        Assert.Equal("24", vfp.EvalExpression("lcIds").AsString);
    }
}
